command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: NURTIS SCHMEICHELN (Ausführung)
// ==========================================

(async () => {
    // --- 1. FRAMEWORK LADEN ---
    const fwMacro = await fromUuid("Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn");
    if (fwMacro) { await fwMacro.execute(); }

    const DSK_FW = globalThis.DSK || DSK;
    if (typeof DSK_FW === "undefined") return ui.notifications.error("Luna sagt 🌙: Framework fehlt!");

    const gabenName = "Nurtis Schmeicheln";
    const ahne = "Nurti";
    const finalEffektName = `${gabenName} (${ahne})`;
    const iconBild = DSK_FW.Symbol(ahne);

    if (DSK_FW.EffektEnde) {
        DSK_FW.EffektEnde.Register("nurtiSchmeicheln", finalEffektName, "Der magische Zwang zu streicheln vergeht. Beide sind wieder frei.");
    }

    const getOwners = (act) => Object.entries(act?.ownership || {}).filter(([id, lvl]) => lvl === 3 && id !== "default").map(([id]) => id);

    // --- 2. CASTER ERMITTELN ---
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character;
    if (!casterActor) casterActor = game.actors.find(a => a.getFlag("world", "letzteGabenQS") !== undefined);
    if (!casterActor) {
        for (let t of canvas.tokens.placeables) {
            if (t.actor && t.actor.getFlag("world", "letzteGabenQS") !== undefined) { casterActor = t.actor; break; }
        }
    }
    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden!");

    const qsWert = Number(casterActor.getFlag("world", "letzteGabenQS") || 1);
    const alteMessageId = casterActor.getFlag("world", "letzteGabenMessageId");
    let whisperTargets = [...new Set([...game.users.filter(u => u.isGM).map(u => u.id), ...getOwners(casterActor)])].filter(id => game.users.get(id));

    // --- 3. FUNKTION FÜR FEHLERMELDUNGEN ---
    const sendError = async (grund) => {
        const infoHtml = `
            <div style="font-family: 'Signika', sans-serif;">
                <div class="dskbox1">
                    <p style="display:flex; gap:8px; align-items:center; margin:0;">
                        <img src="${iconBild}" style="width:28px; border:none; background:transparent;">
                        <b style="font-size: 1.05em;">Information</b>
                    </p>
                    <p style="font-weight:bold; margin-top:6px; margin-bottom:0;">${finalEffektName}</p>
                </div>
                <div class="dskbox2" style="margin-top:10px; text-align: center;">
                    <p style="margin-bottom: 8px; color: #8b0000;"><b>Fehlschlag!</b></p>
                    <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                    <p style="margin-bottom: 8px;">${grund}</p>
                </div>
            </div>
        `;
        await ChatMessage.create({ whisper: whisperTargets, speaker: { alias: "System" }, content: infoHtml });
    };

    // --- 4. ZIEL ERMITTELN & PRÜFEN ---
    const targets = Array.from(game.user.targets);
    if (targets.length === 0) return ui.notifications.warn("Luna sagt 🌙: Bitte wähle zuerst ein Ziel (Target) aus!");

    const targetToken = targets[0];
    const targetActor = targetToken.actor;
    const targetName = targetActor.name;
    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // Nur Menschen können verzaubert werden!
    if (!DSK_FW.Wesen.match(targetActor, ["mensch", "menschen"])) {
        return sendError(`<b>${targetName}</b> ist kein Mensch. Diese Gabe wirkt nur bei menschlichen Wesen.`);
    }

    // --- 5. BERECHNUNGEN (ERFOLG) ---
    const dauerMinuten = qsWert;
    const willenskraftMalus = qsWert * 2;

    await casterActor.unsetFlag("world", "letzteGabenQS");
    await casterActor.unsetFlag("world", "letzteGabenMessageId");

    let alterEffektZiel = targetActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffektZiel) await alterEffektZiel.delete();

    let alterEffektCaster = casterActor.effects.find(e => (e.name || e.label) === finalEffektName);
    if (alterEffektCaster) await alterEffektCaster.delete();

    // --- 6. EFFEKTE AUF BEIDE ANWENDEN (MIT KETTEN-FLAG & VERZÖGERUNG) ---

    // 6a. Effekt für den Menschen (Ziel) MIT dem Malus!
    await targetActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { minutes: dauerMinuten },
        description: `Wird vom Nurtikind (${casterName}) dazu gezwungen, es zu streicheln. Um aufzuhören, ist eine um -${willenskraftMalus} erschwerte Willenskraft-Probe nötig.`,
        changes: [{ 
            key: "system.skillModifiers.FW", 
            mode: 0, 
            value: `Willenskraft -${willenskraftMalus}`, 
            priority: 20 
        }],
        flags: { dsk: { ahne: ahne, linkedActorUuid: casterActor.uuid } }
    }]);

    // ⏱️ Lunas Sicherheits-Atemzug beim Erstellen
    await new Promise(resolve => setTimeout(resolve, 300));

    // 6b. Effekt für das Nurtikind (Wirkender) OHNE Malus!
    await casterActor.createEmbeddedDocuments("ActiveEffect", [{
        name: finalEffektName,
        icon: iconBild,
        img: iconBild,
        duration: { minutes: dauerMinuten },
        description: `Lässt sich genüsslich von ${targetName} streicheln. Die Gabe bindet beide an diese Handlung. Wird das Nurtikind angegriffen, endet der Zwang sofort.`,
        flags: { dsk: { ahne: ahne, linkedActorUuid: targetActor.uuid } }
    }]);

    // --- 7. AUTOMATISCHER KETTEN-AUFLÖSER ---
    if (!globalThis.DSK_SchmeichelnCleanup) {
        globalThis.DSK_SchmeichelnCleanup = true;
        Hooks.on("deleteActiveEffect", async (effect) => {
            if (!game.user.isGM) return;
            const effName = effect.name || effect.label || "";
            if (effName === finalEffektName) {
                const linkedUuid = effect.getFlag("dsk", "linkedActorUuid");
                if (linkedUuid) {
                    const linkedActorDoc = await fromUuid(linkedUuid);
                    const linkedActor = linkedActorDoc?.documentName === "Token" ? linkedActorDoc.actor : linkedActorDoc;
                    if (linkedActor) {
                        const parentUuid = effect.parent.uuid;
                        const linkedEffect = linkedActor.effects.find(e => (e.name || e.label) === effName && e.getFlag("dsk", "linkedActorUuid") === parentUuid);
                        if (linkedEffect) {
                            // ⏱️ Lunas Sicherheits-Atemzug beim Löschen (100ms)
                            setTimeout(async () => {
                                await linkedEffect.delete();
                            }, 100);
                        }
                    }
                }
            }
        });
    }

    // --- 8. CHAT NACHRICHT GENERIEREN ---
    const thinStyle = 'style="font-weight: 300; font-size: 0.9em; opacity: 0.8;"';

    const successContent = `
        <div style="font-family: 'Signika', sans-serif;">
            ${DSK_FW.UI.Header(finalEffektName, iconBild)}
            <div class="dskbox2" style="margin-top:10px;">
                <p><b>${casterName}</b> zwingt <b>${targetName}</b> zu einer ausgedehnten Streicheleinheit.</p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="margin-bottom: 8px;">
                    Der betroffene Mensch ist gezwungen, das Nurtikind während der Wirkungsdauer zu streicheln. Beide sind für diese Zeit gebunden.<br><br>
                    Um diesen Zustand vorzeitig zu beenden, muss <b>${targetName}</b> eine um <b>${willenskraftMalus} erschwerte Probe</b> auf <b>Willenskraft</b> gelingen.
                </p>
                <p style="font-size: 0.85em; color: #555;"><i>Wird das Nurtikind angegriffen oder muss um Leib und Leben fürchten, endet die Wirkung für beide augenblicklich.</i></p>
                <hr style="margin: 8px 0; border: 0; border-top: 1px solid #c9bca6;">
                <p style="text-align:center; font-weight:bold;">Wirkungsdauer:<br>${dauerMinuten} Minuten <span ${thinStyle}>(${qsWert} QS)</span></p>
            </div>
        </div>
    `;

    let msg = alteMessageId ? game.messages.get(alteMessageId) : null;
    if (msg) {
        await msg.update({ content: successContent });
    } else {
        await ChatMessage.create({ content: successContent, speaker: { alias: "System" } });
    }
})();
